export async function boundedText(request: Request, maxBytes: number): Promise<string | null> {
  const declared = Number(request.headers.get('content-length'))
  if (declared > maxBytes) return null
  const text = await request.text()
  return new TextEncoder().encode(text).length > maxBytes ? null : text
}
No file in the repo calls it. contact.ts:129, checkout.ts:249 and resend-webhook.ts:121 each copy the same pattern: a Content-Length check, then `await request.text()`, then a size check afterwards.

