export function declaredParts(declared: TicketRequest): Array<{ part: string; bytes: number }> {
  return [
    { part: 'original', bytes: declared.original.bytes },
    ...declared.derivatives.map((d) => ({ part: `w${d.width}`, bytes: d.bytes })),
  ]
}
